#ifndef CACHE_ENTRY_h
#define CACHE_ENTRY_h

////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////

constexpr uint8_t RRIP_MAX = 7;

////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////

struct CacheEntry
{
    bool valid =false;
    bool dirty =false;
    uint64_t address;
    /*
     * Replacement policy data:
     * */
    uint64_t timestamp;
    int8_t  rrpv;

    bool likely_dead =false;

    CacheEntry(void) =default;
};

////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////

struct MSHREntry
{
    bool is_fired =false;
    bool is_for_write_allocate;
    Transaction trans;

    uint64_t cycle_fired;

    MSHREntry(Transaction&& t, bool is_write=false)
        :is_for_write_allocate(is_write),
        trans(std::move(t)),
        cycle_fired(GL_CYCLE)
    {}
};

////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////

enum class DRAMWriteHint { NONE, CLOSE_AFTER, KEEP_OPEN };

struct WBQueueEntry
{
    Transaction trans;
    DRAMWriteHint dram_write_hint =DRAMWriteHint::NONE;

    WBQueueEntry(Transaction&& t)
        :trans(std::move(t))
    {}
};

////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////

#endif  // CACHE_ENTRY_h
